function approveAndCall(address _spender, uint256 _value, bytes _extraData) public returns (bool success) {
                require(approve(_spender, _value));
                ApproveAndCallFallBack(_spender).receiveApproval(msg.sender, _value, this, _extraData);
                return true;
            }

function approveAndCallcode(address _spender, uint256 _value, bytes _extraData) public returns (bool success) {
                require(approve(_spender, _value));
                ApproveAndCallFallBack(_spender).receiveApproval.value(msg.value)(msg.sender, _value, this, _extraData);
                return true;
            }

function transfer(address _to, uint256 _value) public returns (bool success) {
                require(_value <= balances[msg.sender]);
                balances[msg.sender] = balances[msg.sender].sub(_value);
                balances[_to] = balances[_to].add(_value);
                Transfer(msg.sender, _to, _value);
                return true;
            }

function transferFrom(address _from, address _to, uint256 _value) public returns (bool success) {
                require(_value <= balances[_from]);
                require(_value <= allowed[_from][msg.sender]);
                balances[_from] = balances[_from].sub(_value);
                allowed[_from][msg.sender] = allowed[_from][msg.sender].sub(_value);
                balances[_to] = balances[_to].add(_value);
                Transfer(_from, _to, _value);
                return true;
            }
